modelica_source:
model Baseline
  extends ModelicaTest.Magnetic.FluxTubes.Sensors;
end Baseline;
model BUG010
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(material(B_myMax=0)));
end BUG010;
model BUG011
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(l=0));
end BUG011;
model BUG025
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(area=0));
end BUG025;
model FinalBUG010
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(material(final B_myMax=0)));
end FinalBUG010;
model FinalBUG011
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(final l=0));
end FinalBUG011;
model FinalBUG025
  extends ModelicaTest.Magnetic.FluxTubes.Sensors(genericFluxTube(final area=0));
end FinalBUG025;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG010\n");
simulate(BUG010, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG011\n");
simulate(BUG011, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG025\n");
simulate(BUG025, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG010\n");
simulate(FinalBUG010, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG011\n");
simulate(FinalBUG011, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG025\n");
simulate(FinalBUG025, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG010\n");
system("./Baseline -override genericFluxTube.material.B_myMax=0 -r=BUG010_override.csv");
print("AUDIT_OVERRIDE BUG011\n");
system("./Baseline -override genericFluxTube.l=0 -r=BUG011_override.csv");
print("AUDIT_OVERRIDE BUG025\n");
system("./Baseline -override genericFluxTube.area=0 -r=BUG025_override.csv");
